face.layout_source:
// stereo-ducker.face: the panel for tap/examples/graphs/stereo-ducker.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/graphs/stereo-ducker.face --meta <graph>.cragmeta

face "Stereo Ducker" {
  row(gap = 10) {
    box "Sidechain" { knob.big "Threshold" (ducker.threshold) knob "Ratio" (ducker.ratio) }
    box "Left" { knob "Attack" (left.attack) knob "Release" (left.release) bar "Duck" (duck_l) }
    box "Right" { knob "Attack" (right.attack) knob "Release" (right.release) bar "Duck" (duck_r) }
  }
}
